#!/usr/bin/env bash
set -Eeuo pipefail

VERSION="3.0.0"
REV="MASTER-GROUNDUP-7"
APP_VERSION="NOVA-3.0.0-MASTER-GROUNDUP-7"
EXPECTED_ZIP_SHA256="870da1b5837fd7339c77a6a7543a675cefe73838756e10112280b928fdeec651"
IMAGE="quant-nova:3.0.0-master-groundup-7-${EXPECTED_ZIP_SHA256:0:12}"
APP_DIR="${NOVA_APP_DIR:-$HOME/quant-nova}"
ENV_FILE="$APP_DIR/.env"
DATA_DIR="$APP_DIR/data"
NOVA30_DIR="$APP_DIR/data-nova30"
CONTAINER="quant-nova"
NETWORK="kiwoom-net"
HOST_PORT="${NOVA_HOST_PORT:-3200}"
STAMP="$(date +%Y%m%d%H%M%S)"
TMP="$(mktemp -d)"
BASE_DATA="$TMP/base-data"
FAILED_DATA="$APP_DIR/data-nova30-failed-$STAMP"
BACKUP="quant-nova-backup-master-groundup7-${STAMP}"
CANDIDATE="quant-nova-candidate-master-groundup7-${STAMP}"
ZIP="$TMP/QUANT_NOVA_3.0.0_MASTER_GROUNDUP_7.zip"
SRC="$TMP/nova3000"
CAND_DATA="$TMP/candidate-data"
DEPLOY_DIR="$APP_DIR/deployments/nova3000-master-groundup7-$STAMP"
GUARD_STATIC="$APP_DIR/http-guard-v2/static"
GUARD_CACHE="$APP_DIR/http-guard-v2/cache"
GUARD_BK="$DEPLOY_DIR/http-guard-before"
OLD_EXISTS=0; OLD_STOPPED=0; OLD_RENAMED=0; NEW_STARTED=0; GUARD_BACKUP_READY=0; SUCCESS=0; REAL_FEED_RESULT="NOT_RUN"; ACTIVE_DATA_MUTATED=0

say(){ printf '\n==> %s\n' "$*"; }
die(){ echo "ERROR: $*" >&2; exit 1; }

rollback(){
  local ec=$?
  trap - EXIT
  if [[ $SUCCESS -eq 1 ]]; then rm -rf "$TMP"; exit 0; fi
  echo "[AUTO-ROLLBACK] NOVA 3.0 배포 미완료 — 기존 immutable active 복구" >&2
  # Once the old container was renamed, any container using $CONTAINER is the new attempt.
  # Remove it even if `docker run` failed before NEW_STARTED could be set (e.g. port/start error).
  if [[ $OLD_RENAMED -eq 1 ]] && sudo docker inspect "$CONTAINER" >/dev/null 2>&1; then
    timeout 15 sudo docker stop -t 5 "$CONTAINER" >/dev/null 2>&1 || sudo docker kill "$CONTAINER" >/dev/null 2>&1 || true
    sudo docker rm -f "$CONTAINER" >/dev/null 2>&1 || true
  elif [[ $NEW_STARTED -eq 1 ]] && sudo docker inspect "$CONTAINER" >/dev/null 2>&1; then
    timeout 15 sudo docker stop -t 5 "$CONTAINER" >/dev/null 2>&1 || sudo docker kill "$CONTAINER" >/dev/null 2>&1 || true
    sudo docker rm -f "$CONTAINER" >/dev/null 2>&1 || true
  fi
  sudo docker rm -f "$CANDIDATE" >/dev/null 2>&1 || true
  if [[ $ACTIVE_DATA_MUTATED -eq 1 && -d "$BASE_DATA/nova30" ]]; then
    if [[ -e "$NOVA30_DIR" ]]; then
      sudo rm -rf "$FAILED_DATA" >/dev/null 2>&1 || true
      sudo mv "$NOVA30_DIR" "$FAILED_DATA" >/dev/null 2>&1 || true
    fi
    sudo mkdir -p "$NOVA30_DIR" >/dev/null 2>&1 || true
    sudo chown "$(id -u):$(id -g)" "$NOVA30_DIR" >/dev/null 2>&1 || true
    cp -a "$BASE_DATA/nova30"/. "$NOVA30_DIR"/ >/dev/null 2>&1 || true
    echo "[AUTO-ROLLBACK] NOVA30 runtime data restored; failed state preserved at $FAILED_DATA" >&2
  fi
  if [[ $OLD_RENAMED -eq 1 ]] && sudo docker inspect "$BACKUP" >/dev/null 2>&1; then
    sudo docker rename "$BACKUP" "$CONTAINER" >/dev/null 2>&1 || true
    sudo docker start "$CONTAINER" >/dev/null 2>&1 || true
  elif [[ $OLD_EXISTS -eq 1 ]] && sudo docker inspect "$CONTAINER" >/dev/null 2>&1; then
    sudo docker start "$CONTAINER" >/dev/null 2>&1 || true
  fi
  if [[ $GUARD_BACKUP_READY -eq 1 && -d "$GUARD_BK" && -d "$GUARD_STATIC" ]]; then
    for f in index.html nova.js nova.css manifest.webmanifest sw.js; do sudo rm -f "$GUARD_STATIC/$f" "$GUARD_STATIC/.$f.nova30.tmp" >/dev/null 2>&1 || true; done
    sudo cp -a "$GUARD_BK"/. "$GUARD_STATIC"/ >/dev/null 2>&1 || true
    sudo rm -f "$GUARD_CACHE"/* >/dev/null 2>&1 || true
  fi
  rm -rf "$TMP"
  exit "${ec:-1}"
}
trap rollback EXIT

[[ "${EUID:-$(id -u)}" -ne 0 ]] || die "root로 실행하지 마십시오. ubuntu 사용자에서 실행하세요."
for x in sudo python3 sha256sum base64 curl timeout free df du tar find; do command -v "$x" >/dev/null || die "$x 없음"; done
sudo docker version >/dev/null 2>&1 || die "Docker 접근 실패"
[[ -s "$ENV_FILE" ]] || die "$ENV_FILE 없음/비어 있음"
[[ -d "$DATA_DIR" ]] || die "$DATA_DIR 없음"
sudo test -d "$DATA_DIR" || die "$DATA_DIR 접근 실패"
# Legacy data can intentionally contain root-only secrets (e.g. VAPID PEM). G6 never chmod/chown/copies
# the whole legacy tree; only NOVA30-owned state and one explicit prior-close bridge file are read via sudo.
if [[ -L "$NOVA30_DIR" ]]; then die "$NOVA30_DIR symlink 금지"; fi
if [[ -e "$NOVA30_DIR" && ! -d "$NOVA30_DIR" ]]; then die "$NOVA30_DIR 가 디렉터리가 아님"; fi

say "1/15 Embedded source integrity"
base64 -d > "$ZIP" <<'__PAYLOAD__'
