say "3/15 Existing active + host safety preflight"
if sudo docker inspect "$CONTAINER" >/dev/null 2>&1; then OLD_EXISTS=1; fi
[[ $OLD_EXISTS -eq 1 ]] || die "기존 quant-nova 컨테이너 없음 — 안전 rollback 기준선이 필요합니다."
OLD_STATUS="$(sudo docker inspect -f '{{.State.Status}}' "$CONTAINER")"
[[ "$OLD_STATUS" == "running" ]] || die "기존 quant-nova가 running 상태가 아님: $OLD_STATUS"
OLD_IMAGE_ID="$(sudo docker inspect -f '{{.Image}}' "$CONTAINER")"
SOURCE_NOVA30=""
if [[ -d "$NOVA30_DIR" ]]; then SOURCE_NOVA30="$NOVA30_DIR"; elif sudo test -d "$DATA_DIR/nova30"; then SOURCE_NOVA30="$DATA_DIR/nova30"; fi
if [[ -n "$SOURCE_NOVA30" ]]; then
  BAD_LINK="$(sudo find "$SOURCE_NOVA30" -xdev -type l -print -quit 2>/dev/null || true)"
  [[ -z "$BAD_LINK" ]] || die "NOVA30 runtime data에 symlink 존재: $BAD_LINK"
  BAD_SPECIAL="$(sudo find "$SOURCE_NOVA30" -xdev \( -type b -o -type c -o -type p -o -type s \) -print -quit 2>/dev/null || true)"
  [[ -z "$BAD_SPECIAL" ]] || die "NOVA30 runtime data에 특수파일 존재: $BAD_SPECIAL"
  NOVA30_KB="$(sudo du -sk "$SOURCE_NOVA30" | awk '{print $1}')"
else NOVA30_KB=0; fi
DATA_KB="$(sudo du -sk "$DATA_DIR" | awk '{print $1}')"
FREE_KB="$(df -Pk "$APP_DIR" | awk 'NR==2{print $4}')"
NEED_KB=$((NOVA30_KB * 3 + 1400000))
(( FREE_KB > NEED_KB )) || die "디스크 여유 부족: free=${FREE_KB}KB need>${NEED_KB}KB"
printf 'OLD_IMAGE_ID=%s\nOLD_STATUS=%s\nLEGACY_DATA_KB=%s\nNOVA30_KB=%s\nFREE_KB=%s\nSOURCE_NOVA30=%s\n' "$OLD_IMAGE_ID" "$OLD_STATUS" "$DATA_KB" "$NOVA30_KB" "$FREE_KB" "${SOURCE_NOVA30:-EMPTY}"

say "4/15 Freeze old active — no rename/delete/mutation"
timeout 20 sudo docker stop -t 8 "$CONTAINER" >/dev/null 2>&1 || sudo docker kill "$CONTAINER" >/dev/null 2>&1 || die "기존 active 정지 실패"
[[ "$(sudo docker inspect -f '{{.State.Running}}' "$CONTAINER")" == "false" ]] || die "기존 active가 아직 실행 중"
OLD_STOPPED=1
for _ in $(seq 1 30); do AVAIL_MB="$(free -m | awk '/Mem:/{print $7}')"; (( AVAIL_MB >= 280 )) && break; sleep 1; done
(( AVAIL_MB >= 280 )) || die "기존 active 정지 후 available RAM ${AVAIL_MB}MB < 280MB"
echo "OLD_ACTIVE_FROZEN=PASS available=${AVAIL_MB}MB"

